CREATE TABLE IF NOT EXISTS faction_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,faction_id BIGINT UNSIGNED NOT NULL,character_id BIGINT UNSIGNED NULL,action VARCHAR(64) NOT NULL,details_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(faction_id,created_at),FOREIGN KEY(faction_id) REFERENCES factions(id) ON DELETE CASCADE);
ALTER TABLE businesses ADD COLUMN tax_amount BIGINT NOT NULL DEFAULT 0;
ALTER TABLE businesses ADD COLUMN tax_due_at DATETIME NULL;
ALTER TABLE businesses ADD COLUMN stock BIGINT NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS business_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,character_id BIGINT UNSIGNED NULL,type VARCHAR(48) NOT NULL,amount BIGINT NOT NULL,details_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(business_id,created_at),FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS job_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,character_id BIGINT UNSIGNED NOT NULL,job_name VARCHAR(64) NOT NULL,reward BIGINT NOT NULL DEFAULT 0,details_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(character_id,created_at),FOREIGN KEY(character_id) REFERENCES characters(id) ON DELETE CASCADE);
